  ('9d3320d4-9454-52d8-b6fe-27cd8203081f', null, (select id from public.skills where slug = 'read-g4-evidence-inference'), null, 'hard',
   $q$Jamal thought his sheet was perfect for a birthday card. Which detail best supports his idea?$q$, $q$[{"text":"The finished paper was thicker than notebook paper.","is_correct":true},{"text":"A helper used a blender to make the pulp.","is_correct":false,"misconception_token":"wrong-supporting-detail"},{"text":"The students stirred the pulp in a big tub.","is_correct":false,"misconception_token":"wrong-supporting-detail"},{"text":"The students soaked the paper in warm water.","is_correct":false,"misconception_token":"wrong-supporting-detail"}]$q$::jsonb, $q$The finished paper was thicker than notebook paper.$q$, $q$A card needs to be stiff, and the passage says the paper was "thicker than notebook paper." The blender detail explains how the paper was made, not why it suits a card.$q$, 'draft', 'ee21fe15-be92-549a-b517-6f490b41ac70')
